<template>
<div class="app-container">
  <el-form :inline="true"><el-form-item label="课题"><el-select v-model="topicId" filterable style="width:360px" @change="reload"><el-option v-for="t in topics" :key="t.topicId" :label="t.topicName" :value="t.topicId"/></el-select></el-form-item></el-form>
  <el-row v-if="overview" :gutter="12" class="mb8"><el-col :span="6"><el-card>总资金<br><b>{{money(overview.totalAmount)}}</b></el-card></el-col><el-col :span="6"><el-card>计划拨付<br><b>{{money(overview.plannedAllocation)}}</b></el-card></el-col><el-col :span="6"><el-card>实际拨付<br><b>{{money(overview.actualAllocation)}}</b></el-card></el-col><el-col :span="6"><el-card>剩余可拨<br><b>{{money(overview.remainingAllocation)}}</b></el-card></el-col></el-row>
  <el-button class="mb8" type="primary" plain size="mini" icon="el-icon-plus" :disabled="!topicId" v-hasPermi="['fund:allocation:add']" @click="openPlan()">新增拨付计划</el-button>
  <el-table v-loading="loading" :data="plans">
    <el-table-column label="拨付名称" prop="allocationName" min-width="160"/><el-table-column label="拨付单位" prop="allocationDeptName" min-width="130"/><el-table-column label="接收单位" prop="receiveDeptName" min-width="130"/>
    <el-table-column label="计划金额" width="125"><template slot-scope="s">{{money(s.row.planAmount)}}</template></el-table-column><el-table-column label="实际金额" width="125"><template slot-scope="s">{{money(s.row.actualAmount)}}</template></el-table-column><el-table-column label="差额" width="125"><template slot-scope="s">{{signedMoney(s.row.differenceAmount)}}</template></el-table-column>
    <el-table-column label="执行结果" width="110"><template slot-scope="s"><el-tag :type="resultType(s.row)">{{resultText(s.row)}}</el-tag></template></el-table-column><el-table-column label="责任人" prop="responsibleUserName" width="110"/><el-table-column label="状态" width="90"><template slot-scope="s">{{s.row.status==='1'?'已结束':'执行中'}}</template></el-table-column><el-table-column label="结束原因" prop="finishReason" min-width="160" show-overflow-tooltip/><el-table-column label="完成时间" prop="finishTime" width="165"/>
    <el-table-column label="操作" fixed="right" width="330"><template slot-scope="s"><div class="business-table-actions"><el-button type="text" @click="openRecords(s.row)">拨付记录</el-button><el-button type="text" @click="showHistory('ALLOCATION_PLAN',s.row.planId)">操作历史</el-button><el-button v-if="s.row.status==='0'" type="text" v-hasPermi="['fund:allocation:assign']" @click="openAssign(s.row)">责任人</el-button><el-button v-if="s.row.status==='0'" type="text" v-hasPermi="['fund:allocation:edit']" @click="openPlan(s.row)">编辑</el-button><el-button v-if="s.row.status==='0'" type="text" v-hasPermi="['fund:allocation:finish']" @click="finishPlan(s.row)">结束</el-button></div></template></el-table-column>
  </el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadPlans"/>

  <el-dialog :title="planForm.planId?'编辑拨付计划':'新增拨付计划'" :visible.sync="planOpen" width="650px"><el-form ref="planForm" :model="planForm" :rules="planRules" label-width="100px"><el-form-item label="拨付名称" prop="allocationName"><el-input v-model="planForm.allocationName"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="拨付单位" prop="allocationDeptId"><el-select v-model="planForm.allocationDeptId" filterable style="width:100%"><el-option v-for="d in depts" :key="d.deptId" :label="d.deptName" :value="d.deptId"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="接收单位" prop="receiveDeptId"><el-select v-model="planForm.receiveDeptId" filterable style="width:100%"><el-option v-for="d in depts" :key="d.deptId" :label="d.deptName" :value="d.deptId"/></el-select></el-form-item></el-col></el-row><el-form-item label="拨付金额" prop="planAmount"><el-input-number v-model="planForm.planAmount" :precision="2" :min="0.01" :step="10000" style="width:100%"/></el-form-item><el-form-item label="拨付时间"><el-date-picker v-model="planForm.planTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input v-model="planForm.fundDesc" type="textarea"/></el-form-item></el-form><div slot="footer"><el-button @click="planOpen=false">取消</el-button><el-button type="primary" @click="savePlan">确定</el-button></div></el-dialog>
  <el-dialog title="指定责任人" :visible.sync="assignOpen" width="460px"><el-select v-model="assignUserId" clearable filterable style="width:100%"><el-option v-for="u in assignUsers" :key="u.userId" :label="u.nickName||u.userName" :value="u.userId"/></el-select><div slot="footer"><el-button @click="assignOpen=false">取消</el-button><el-button type="primary" @click="saveAssign">确定</el-button></div></el-dialog>
  <el-dialog :title="recordPlan.allocationName+' - 拨付记录'" :visible.sync="recordsOpen" width="1000px"><el-button v-if="recordPlan.status==='0'" type="primary" plain size="mini" v-hasPermi="['fund:allocation:submit']" @click="openRecord()">提交拨付</el-button><el-table :data="records"><el-table-column label="名称" prop="allocationName"/><el-table-column label="金额" width="120"><template slot-scope="s">{{money(s.row.amount)}}</template></el-table-column><el-table-column label="提交人" prop="submitUserName" width="110"/><el-table-column label="时间" prop="allocationTime" width="165"/><el-table-column label="附件" min-width="180"><template slot-scope="s"><el-button v-for="a in s.row.attachments||[]" :key="a.attachmentId" type="text" @click="downloadAttachment(a)">{{a.originalName}}</el-button><span v-if="!s.row.attachments||!s.row.attachments.length">-</span></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="s"><div class="business-table-actions"><el-button type="text" @click="showHistory('ALLOCATION_RECORD',s.row.recordId)">历史</el-button><el-button v-if="recordPlan.status==='0'" type="text" @click="openRecord(s.row)">编辑</el-button><el-button v-if="recordPlan.status==='0'" type="text" @click="deleteRecord(s.row)">删除</el-button></div></template></el-table-column></el-table></el-dialog>
  <el-dialog title="拨付记录" :visible.sync="recordOpen" width="620px"><el-form ref="recordForm" :model="recordForm" :rules="recordRules" label-width="100px"><el-form-item label="拨付名称" prop="allocationName"><el-input v-model="recordForm.allocationName"/></el-form-item><el-form-item label="拨付金额" prop="amount"><el-input-number v-model="recordForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="拨付时间" prop="allocationTime"><el-date-picker v-model="recordForm.allocationTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input v-model="recordForm.fundDesc" type="textarea"/></el-form-item><el-form-item v-if="existingAttachments.length" label="已有附件"><el-button v-for="a in existingAttachments" :key="a.attachmentId" type="text" @click="downloadAttachment(a)">{{a.originalName}}</el-button></el-form-item><el-form-item :label="existingAttachments.length?'新增附件':'拨付凭证'"><file-upload v-model="recordForm.voucherUrls" :limit="5" :file-type="allowedFileTypes"/></el-form-item></el-form><div slot="footer"><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" @click="saveRecord">确定</el-button></div></el-dialog>
  <el-dialog title="操作历史" :visible.sync="historyOpen" width="760px"><el-table :data="history"><el-table-column label="操作" width="150"><template slot-scope="s">{{operationText(s.row.operationType)}}</template></el-table-column><el-table-column label="操作人ID" prop="operatorId" width="110"/><el-table-column label="时间" prop="operationTime" width="165"/><el-table-column label="原因" prop="reason" min-width="220" show-overflow-tooltip/></el-table></el-dialog>
</div>
</template>
<script>
import {groupOptions} from '@/api/research/group'
import {getAllocationOverview} from '@/api/fund/budget'
import {listFundDepts,listFundUsers} from '@/api/fund/org'
import {listAllocationPlans,addAllocationPlan,updateAllocationPlan,assignAllocation,listAllocationRecords,addAllocationRecord,updateAllocationRecord,delAllocationRecord,allocationFinishCheck,finishAllocation} from '@/api/fund/allocation'
import {downloadFundAttachment} from '@/api/fund/attachment'
import {listFundOperationLogs} from '@/api/fund/operationLog'
export default{name:'FundAllocation',data(){return{topics:[],topicId:null,overview:null,depts:[],plans:[],loading:false,total:0,query:{pageNum:1,pageSize:10},planOpen:false,planForm:{},assignOpen:false,assignPlan:null,assignUsers:[],assignUserId:null,recordsOpen:false,recordPlan:{},records:[],recordOpen:false,recordForm:{},existingAttachments:[],historyOpen:false,history:[],allowedFileTypes:['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'],planRules:{allocationName:[{required:true,message:'请输入拨付名称'}],allocationDeptId:[{required:true,message:'请选择拨付单位'}],receiveDeptId:[{required:true,message:'请选择接收单位'}],planAmount:[{required:true,message:'请输入金额'}]},recordRules:{allocationName:[{required:true,message:'请输入名称'}],amount:[{required:true,message:'请输入金额'}],allocationTime:[{required:true,message:'请选择时间'}]}}},created(){listFundDepts().then(r=>{this.depts=r.data||[]});groupOptions().then(r=>{this.topics=(r.data||[]).map(g=>({topicId:g.groupId,topicName:g.groupName}));if(this.topics.length){this.topicId=this.topics[0].topicId;this.reload()}})},methods:{money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})},signedMoney(v){const n=Number(v||0);return(n>0?'+':'')+this.money(n)},resultText(r){if(r.status!=='1')return'执行中';return{'0':'按计划完成','1':'低于计划','2':'超出计划'}[r.finishType]||'已结束'},resultType(r){return r.status!=='1'?'info':(r.finishType==='0'?'success':'warning')},operationText(t){return{CREATE_PLAN:'创建计划',UPDATE_PLAN:'修改计划',CHANGE_PLAN_AMOUNT:'变更计划金额',ASSIGN_RESPONSIBLE:'指定责任人',CHANGE_RESPONSIBLE:'变更责任人',CREATE_RECORD:'创建记录',UPDATE_RECORD:'修改记录',DELETE_RECORD:'删除记录',CLOSE_ALLOCATION:'结束拨付'}[t]||t},reload(){this.loadPlans();getAllocationOverview(this.topicId).then(r=>{this.overview=r.data}).catch(()=>{this.overview=null})},loadPlans(){if(!this.topicId)return;this.loading=true;listAllocationPlans(Object.assign({},this.query,{topicId:this.topicId})).then(r=>{this.plans=r.rows;this.total=r.total}).finally(()=>{this.loading=false})},openPlan(r){this.planForm=r?Object.assign({},r):{topicId:this.topicId,allocationName:'',allocationDeptId:null,receiveDeptId:null,planAmount:0,planTime:null,fundDesc:''};this.planOpen=true},savePlan(){this.$refs.planForm.validate(ok=>{if(!ok)return;(this.planForm.planId?updateAllocationPlan:addAllocationPlan)(this.planForm).then(()=>{this.$modal.msgSuccess('保存成功');this.planOpen=false;this.reload()})})},openAssign(r){this.assignPlan=r;this.assignUserId=r.responsibleUserId;listFundUsers(r.allocationDeptId).then(x=>{this.assignUsers=x.data||[];this.assignOpen=true})},saveAssign(){assignAllocation(this.assignPlan.planId,this.assignUserId).then(()=>{this.$modal.msgSuccess('责任人已更新');this.assignOpen=false;this.loadPlans()})},openRecords(r){this.recordPlan=r;listAllocationRecords(r.planId).then(x=>{this.records=x.data||[];this.recordsOpen=true})},openRecord(r){this.existingAttachments=r&&r.attachments?r.attachments:[];this.recordForm=r?Object.assign({},r,{voucherUrls:null,attachments:undefined}):{planId:this.recordPlan.planId,allocationName:'',amount:0,allocationTime:null,fundDesc:'',voucherUrls:''};this.recordOpen=true},saveRecord(){this.$refs.recordForm.validate(ok=>{if(!ok)return;(this.recordForm.recordId?updateAllocationRecord:addAllocationRecord)(this.recordForm).then(()=>{this.$modal.msgSuccess('保存成功');this.recordOpen=false;this.openRecords(this.recordPlan);this.reload()})})},deleteRecord(r){this.$modal.confirm('确认删除该拨付记录？').then(()=>delAllocationRecord(r.recordId)).then(()=>{this.openRecords(this.recordPlan);this.reload()})},downloadAttachment(a){downloadFundAttachment(a.attachmentId,a.originalName)},showHistory(businessType,businessId){listFundOperationLogs({groupId:this.topicId,businessType,businessId}).then(r=>{this.history=r.data||[];this.historyOpen=true})},finishPlan(row){allocationFinishCheck(row.planId).then(r=>{const c=r.data;if(!c.needConfirm)return this.$modal.confirm('实际金额与计划一致，确认结束？').then(()=>finishAllocation(row.planId,false,null));const text=c.differenceAmount<0?'实际拨付低于计划，请填写结束原因':'实际拨付超出计划，请填写结束原因';return this.$prompt(text,'差异确认',{inputType:'textarea',inputValidator:v=>!!(v&&v.trim())||'结束原因必填'}).then(({value})=>finishAllocation(row.planId,true,value.trim()))}).then(x=>{if(x){this.$modal.msgSuccess('计划已结束');this.reload()}})}}}
</script>
